function main(): void {
  const n = 50;
  const s = new Uint8Array(n + 1);
  for (let i = 2; i <= n; i++) {
    if (!s[i]) {
      for (let j = i * 2; j <= n; j += i) s[j] = 1;
    }
  }
  const primes: number[] = [];
  for (let i = 2; i <= n; i++) if (!s[i]) primes.push(i);
  console.log(primes.join(","), s.length, s instanceof Uint8Array);
  const w = new Uint8Array([1, 255, 256, -1, 1.9]);
  console.log(w, w.length);
  const frac = new Uint8Array(2.7);
  const nan = new Uint8Array(NaN);
  console.log(frac.length, nan.length);
  s[100] = 5;
  s[-1] = 5;
  console.log(s[100], s[-1], s.length);
  try {
    const bad = new Uint8Array(-1);
    console.log(bad.length);
  } catch (e: any) {
    console.log(e.name, e.message);
  }
  const sub = s.subarray(2, 5);
  sub[0] = 9;
  console.log(s[2], Array.from(sub), new Uint8Array(3));
  const v = new Uint8Array(40);
  let total = 0;
  for (let i = 0; i < 20000; i++) v[i % 40] = i;
  for (let i = 0; i < v.length; i++) total += v[i];
  console.log(total, Uint8Array.from([1]) instanceof Uint8Array);
}
